function minimumArea(grid) {
  // Try every rectangle and keep the smallest one that leaves no 1 outside.
  const m = grid.length, n = grid[0].length;
  let best = Infinity;
  for (let r1 = 0; r1 < m; r1++)
    for (let r2 = r1; r2 < m; r2++)
      for (let c1 = 0; c1 < n; c1++)
        for (let c2 = c1; c2 < n; c2++) {
          let covers = true;
          for (let i = 0; i < m && covers; i++)
            for (let j = 0; j < n; j++)
              if (grid[i][j] === 1 && (i < r1 || i > r2 || j < c1 || j > c2)) { covers = false; break; }
          if (covers) best = Math.min(best, (r2 - r1 + 1) * (c2 - c1 + 1));
        }
  return best;
}

