function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 70 + Math.floor(rand() * 31) : 1 + Math.floor(rand() * 6);
  const n = large ? 70 + Math.floor(rand() * 31) : 1 + Math.floor(rand() * 6);
  const span = limit => { const a = Math.floor(rand() * limit), b = Math.floor(rand() * limit); return [Math.min(a, b), Math.max(a, b)]; };
  // Ones fall only inside a random window, so the answer is often smaller than the whole grid.
  const [r1, r2] = span(m), [c1, c2] = span(n);
  const dense = !large && rand() < 0.3;
  const grid = Array.from({ length: m }, (_, i) => Array.from({ length: n }, (_, j) => dense && i >= r1 && i <= r2 && j >= c1 && j <= c2 && rand() < 0.6 ? 1 : 0));
  // At least one 1 is always placed, as the problem guarantees.
  const count = large ? 1 + Math.floor(rand() * 40) : 1 + Math.floor(rand() * 4);
  for (let k = 0; k < count; k++) grid[r1 + Math.floor(rand() * (r2 - r1 + 1))][c1 + Math.floor(rand() * (c2 - c1 + 1))] = 1;
  return [grid];
}
